def data(path,mime):
    return f'data:{mime};base64,'+b64encode(Path(path).read_bytes()).decode()
def ratio(a,b):
    def lum(c):
        v=[int(c[i:i+2],16)/255 for i in (1,3,5)]
        v=[x/12.92 if x<=.04045 else ((x+.055)/1.055)**2.4 for x in v]
        return .2126*v[0]+.7152*v[1]+.0722*v[2]
    x,y=sorted([lum(a),lum(b)])
    return (y+.05)/(x+.05)
def wireframe(name,w,h,blocks):
    out=[f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 {w} {h}" role="img" aria-labelledby="title"><title id="title">{escape(name)}</title><rect width="100%" height="100%" rx="14" fill="#F6F7F9"/><style>text{{font-family:Arial,sans-serif;fill:#0F1B2A;font-size:16px}}.small{{font-size:12px;fill:#536174}}</style>']
    for x,y,bw,bh,title,subtitle in blocks:
        out.append(f'<rect x="{x}" y="{y}" width="{bw}" height="{bh}" rx="7" fill="#FFFFFF" stroke="#94A5B5" stroke-width="1.2"/><text x="{x+16}" y="{y+27}" font-weight="700">{escape(title)}</text>')
        for j,line in enumerate(subtitle.split('|')):
            out.append(f'<text class="small" x="{x+16}" y="{y+49+j*19}">{escape(line)}</text>')
    return ''.join(out)+'</svg>'
