pairs=[('#FFFFFF','#0F1B2A','Primary button text'),('#0F1B2A','#F6F7F9','Body / headings'),('#007E53','#FFFFFF','Accessible green links'),('#536174','#FFFFFF','Secondary body text'),('#0F1B2A','#00A86B','Green action with navy text'),('#E8EDF2','#1B2027','XR primary text'),('#A9B4BF','#1B2027','XR secondary text'),('#7A8D9E','#FFFFFF','Essential control boundary'),('#FFFFFF','#00A86B','Do not use white body text on brand green')]
contrast=[]
for a,b,label in pairs:
    value=ratio(a,b)
    contrast.append({'foreground':a,'background':b,'ratio':round(value,2),'use':label,'normalTextPass':value>=4.5,'uiPass':value>=3})
(DOCS/'CONTRAST-CHECKS.json').write_text(json.dumps(contrast,indent=2)+'\n')
